import { Controller } from '@nestjs/common';

// 이 기능이 새로 만드는 API는 없다.
// GET /approval-documents, GET /approval-documents/:approvalDocumentId 는 먼저 하는 작업에서 한 번만 만든다.
@Controller('api/v1')
export class FnSfr04008Controller {}

