import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, ErrorText, Field, Filters, Num, Pager, Pairs, RefName, Select, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const STATUS_OPTIONS: [string, string][] = STATUSES.map((s): [string, string] => [s, s]);

function DetailDrawer({ id, role, onClose }: { id: number; role: string; onClose: () => void }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', '/approval-documents/' + id, role),
    [id],
  );
  return (
    <Drawer title={'결재문서 상세'} onClose={onClose}>
      {loading && <p>불러오는 중입니다.</p>}
      {error && <ErrorText text={error} />}
      {data && (
        <Pairs
          items={[
            ['결재문서 ID', String(data.approvalDocumentId)],
            ['문서 제목', String(data.title ?? '')],
            ['결재 진행 상태', <Badge value={data.approvalStatus} />],
            ['문서 본문', <pre>{String(data.body ?? '')}</pre>],
          ]}
        />
      )}
    </Drawer>
  );
}

export default function FnSfr04008Page({ role }: PageProps) {
  const [status, setStatus] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<number | null>(null);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/approval-documents', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  const rows = data?.items ?? [];
  const inProgress = rows.filter((r) => r.approvalStatus === '진행중' || r.approvalStatus === '결재대기').length;

  const search = () => {
    if (startDate && endDate && startDate > endDate) {
      window.alert('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setPage(0);
    setApplied({ approvalStatus: status, startDate, endDate });
  };

  const reset = () => {
    setStatus('');
    setStartDate('');
    setEndDate('');
    setPage(0);
    setApplied({});
  };

  return (
    <div className={'bento'}>
      <section className={'box span-8'}>
        <h2>상신 문서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label={'결재 진행 상태'}>
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder={'전체'} />
          </Field>
          <Field label={'조회 시작일'}>
            <input type={'date'} value={startDate} onChange={(e) => setStartDate(e.target.value)} />
          </Field>
          <Field label={'조회 종료일'}>
            <input type={'date'} value={endDate} onChange={(e) => setEndDate(e.target.value)} />
          </Field>
        </Filters>
        {error && <ErrorText text={error} />}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            { key: 'drafterId', label: '기안자', render: (r) => <RefName table={'employee'} role={role} value={r.drafterId} /> },
            { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r.submittedAt} time /> },
          ]}
          rows={rows}
          onRowClick={(r) => setSelectedId(Number(r.approvalDocumentId))}
          empty={loading ? '불러오는 중입니다.' : '상신한 결재문서가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      <section className={'box span-4'}>
        <h2>상신 현황</h2>
        <Tiles
          items={[
            ['조회된 문서', <Num value={data?.total ?? 0} />],
            ['이번 쪽 진행·대기', <Num value={inProgress} />],
          ]}
        />
      </section>
      {selectedId !== null && (
        <DetailDrawer id={selectedId} role={role} onClose={() => setSelectedId(null)} />
      )}
    </div>
  );
}
